import { useState } from 'react';

export default function Login({ onLogin }) {
  const [email, setEmail] = useState('keshav@aria.ai');
  const [password, setPassword] = useState('');

  return (
    <div style={{
      minHeight: '100vh', display: 'flex',
      alignItems: 'center', justifyContent: 'center',
      background: 'var(--bg)', position: 'relative', zIndex: 1
    }}>
      <div style={{
        width: 380, background: 'var(--surface)',
        border: '1px solid var(--border)', borderRadius: 16,
        padding: 32, position: 'relative', overflow: 'hidden'
      }}>
        <div style={{
          position: 'absolute', top: 0, left: 0, right: 0, height: 2,
          background: 'linear-gradient(90deg, #3b82f6, #06b6d4, #8b5cf6)'
        }} />
        <div style={{ fontSize: '1.4rem', fontWeight: 700, marginBottom: 4 }}>Welcome back 👋</div>
        <div style={{ fontSize: '0.75rem', color: 'var(--text2)', marginBottom: 24 }}>Sign in to your ARIA dashboard</div>

        <div style={{ marginBottom: 14 }}>
          <label style={{ fontSize: '0.7rem', color: 'var(--text2)', marginBottom: 6, display: 'block', fontFamily: 'var(--mono)' }}>Email</label>
          <input value={email} onChange={e => setEmail(e.target.value)}
            style={{ width: '100%', background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 8, padding: '10px 14px', color: 'var(--text)', fontFamily: 'var(--sans)', fontSize: '0.85rem', outline: 'none' }}
            type="email" placeholder="you@example.com" />
        </div>

        <div style={{ marginBottom: 18 }}>
          <label style={{ fontSize: '0.7rem', color: 'var(--text2)', marginBottom: 6, display: 'block', fontFamily: 'var(--mono)' }}>Password</label>
          <input value={password} onChange={e => setPassword(e.target.value)}
            style={{ width: '100%', background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 8, padding: '10px 14px', color: 'var(--text)', fontFamily: 'var(--sans)', fontSize: '0.85rem', outline: 'none' }}
            type="password" placeholder="••••••••" />
        </div>

        <button onClick={onLogin} style={{
          width: '100%', padding: 11, borderRadius: 8, border: 'none',
          background: 'linear-gradient(135deg, #3b82f6, #06b6d4)',
          color: '#fff', fontFamily: 'var(--sans)', fontSize: '0.85rem',
          fontWeight: 600, cursor: 'pointer'
        }}>Sign In →</button>

        <div style={{ textAlign: 'center', marginTop: 14, fontSize: '0.65rem', color: 'var(--text3)' }}>
          Secured with JWT · Role-based access
        </div>
      </div>
    </div>
  );
}
